data.Corefile:
.:53 { errors cache 30 {
   loop
   reload
   loadbalance
   forward . /etc/resolv.conf
   health
   prometheus :9153
   ready
   kubernetes cluster.local in-addr.arpa ip6.arpa {
     pods insecure
     fallthrough in-addr.arpa ip6.arpa
   }
   hosts {
     fallthrough
   }
   rewrite name regex (.*)\.svc\.cluster\.local $1.svc.cluster.local
   cache 30
   ttl 300
 }
